mapper.select:
SELECT wd.id, wd.device_no AS deviceNo, wd.model, wd.spec, wd.water_type AS waterType, wd.group_id AS groupId, CONCAT_WS(' / ', park.name, building.name, floor.name) AS groupPath, wd.status, CASE wd.status WHEN 1 THEN '正常' WHEN 0 THEN '停用' ELSE '未知' END AS statusName, wd.pending_retest AS pendingRetest, wd.install_date AS installDate, ${p.sortExpr} AS createTime FROM water_dispenser wd LEFT JOIN building_group floor ON floor.id = wd.group_id LEFT JOIN building_group building ON building.id = floor.parent_id LEFT JOIN building_group park ON park.id = building.parent_id
wd.group_id IN
#{gid}
AND wd.device_no LIKE CONCAT(#{p.deviceNo}, '%')
AND wd.model = #{p.model}
AND wd.spec = #{p.spec}
AND CONCAT(',', COALESCE(wd.water_type, ''), ',') LIKE CONCAT('%,', #{p.waterType}, ',%')
AND wd.status = #{p.status}
AND wd.pending_retest = #{p.pendingRetest}
AND (${p.sortExpr} > #{p.cursorValue} OR (${p.sortExpr} = #{p.cursorValue} AND wd.id > #{p.cursorId}))
AND wd.id > #{p.cursorId}
AND (${p.sortExpr} IS NULL OR ${p.sortExpr} < #{p.cursorValue} OR (${p.sortExpr} = #{p.cursorValue} AND wd.id < #{p.cursorId}))
AND wd.id < #{p.cursorId}
ORDER BY ${p.sortExpr} ASCDESC , wd.id ASCDESC LIMIT #{p.limit}
